def find_boxes(I):
    # 4-connected component of 5s; bounding box; interior = bbox cells not in box & not 5 -> fill if enclosed (surrounded by box ring) 
    H,W=len(I),len(I[0])
    seen=[[False]*W for _ in range(H)]
    boxes=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==5 and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;comp=[]
                while st:
                    a,b=st.pop();comp.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and I[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                rows=[p[0] for p in comp];cols=[p[1] for p in comp]
                top,bot,left,right=min(rows),max(rows),min(cols),max(cols)
                boxes.append((comp,(top,bot,left,right)))
    return boxes

